const money = (value: number) => "GH₵ " + Number(value || 0).toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 });

export default function SellerBalancePayouts({ available, pendingBalance, lifetimeEarnings, withdrawals, transactions, withdrawing, onConfirm }: Props) {
  const webView = useRef<WebView>(null);
  const cards = [{ id: "available", title: "Available balance", value: money(available), icon: "wallet", color: "#F64D86" }, { id: "pending", title: "Pending balance", value: money(pendingBalance), icon: "receipt", color: "#7C486B" }, { id: "lifetime", title: "Lifetime earnings", value: money(lifetimeEarnings), icon: "chart", color: "#171318" }, { id: "withdrawals", title: "Withdrawals", value: money(withdrawals), icon: "arrow", color: "#B06B92" }];
  const presets = Array.from(new Set([available, Math.round(available * 0.5 * 100) / 100, Math.min(100, available)].filter((value) => value > 0))).slice(0, 3);
  const payload = JSON.stringify({ cards, available, presets, transactions, withdrawing }).replace(/</g, "\\u003c");
  const handleMessage = async (event: WebViewMessageEvent) => { const message = event.nativeEvent.data; if (!message.startsWith("withdraw:")) return; const amount = Number(message.slice("withdraw:".length)); try { await onConfirm(amount); webView.current?.injectJavaScript("window.BalanceAnimation && window.BalanceAnimation.done(); true;"); } catch { webView.current?.injectJavaScript("window.BalanceAnimation && window.BalanceAnimation.error(); true;"); } };
  return <View style={s.wrap}><WebView ref={webView} originWhitelist={["*"]} source={{ html: balanceHtml(payload) }} onMessage={handleMessage} javaScriptEnabled scrollEnabled={false} showsVerticalScrollIndicator={false} showsHorizontalScrollIndicator={false} style={[s.webView, { height: 760 + transactions.length * 76 }]} /></View>;
}

const balanceHtml = (payload: string) => "<!doctype html><html><head><meta name=\"viewport\" content=\"width=device-width,initial-scale=1,maximum-scale=1,user-scalable=no\"></head><body><style>" + ANIMATION_CSS + "</style><div id=\"balance-animation-root\"></div><script>window.__BALANCE_DATA__=" + payload + ";</script><script>" + ANIMATION_BUNDLE + "</script></body></html>";

const s = StyleSheet.create({ wrap: { width: "100%" }, webView: { width: "100%", backgroundColor: "transparent" } });